function preload()
{
	soundFormats('mp3', "wav");
  song = loadSound('https://openprocessing.org/sketch/2138012/files/rain.mp3');//load song
}
function setup() 
{
	background(0);
	song.play()
  amp = new p5.Amplitude();
	song.loop()
  createCanvas(1900, 1000);
	for(i=0;i<100;i++)
	{
		 eval("leWave"+i+"=createleWave("+i+");")
	}
}

function draw() 
{
	var vol = amp.getLevel();
  volumeLevel = round(map(vol, 0, 0.3,5, 60));
	frameRate(volumeLevel)
	for(i=0;i<100;i++)
	{
			 eval("updateleWave(leWave"+i+");")
	}
}

function createleWave(i)
{
    let leWave={}
		leWave.xspacing = 15; // Distance between each horizontal location
		leWave.w; // Width of entire wave
		leWave.theta = 0.0; // Start angle at 0
		leWave.amplitude = 35.0; // Height of wave
		leWave.period = 500.0; // How many pixels before the wave repeats
		leWave.dx; // Value for incrementing x
		leWave.yvalues; // Using an array to store height values for the wave
		leWave.w = width + 16;
		leWave.dx = (TWO_PI / leWave.period) * leWave.xspacing;
		leWave.yvalues = new Array(floor(leWave.w / leWave.xspacing));
		leWave.x=random(10)
		leWave.r=random(10)
		leWave.y=random(-500,500)
		leWave.r1=random(255)
		leWave.g1=random(0)
		leWave.b1=random(255)
		return leWave
}


function updateleWave(leWave)
{
  leWave.theta += 0.08;

  // For every x value, calculate a y value with tan function
  let x = leWave.theta;
  for (let i = 0; i < leWave.yvalues.length; i++) 
	{
    leWave.yvalues[i] = tan(x) * leWave.amplitude+leWave.y;
    x += leWave.dx+leWave.x;
  }
  noStroke();
  fill(leWave.r1,leWave.g1,leWave.b1,leWave.b1);
  // A simple way to draw the wave with an ellipse at each location
  for (let x = 0; x < leWave.yvalues.length; x++) {
    ellipse(x * leWave.xspacing, height / 2 + leWave.yvalues[x], leWave.r+random(10));
  }
}

